#include <iomanip>
#include <vector>
using namespace std;

int main() {
    int n, t;
    double p;
    cin >> n >> p >> t;

    vector<double> dp(n + 1);
    for (int i = 0; i <= n; ++i) dp[i] = i;

    for (int step = 0; step < t; ++step) {
        for (int i = n; i >= 1; --i) {
            dp[i] = p * dp[i - 1] + (1.0 - p) * dp[i];
        }
    }

    cout << setprecision(10) << n - dp[n] << '\n';
    return 0;
}

