#include <iostream>
#include <iomanip>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, t;
    double p;
    cin >> n >> p >> t;

    if (n >= t) {
        cout << setprecision(10) << p * t << '\n';
        return 0;
    }

    vector<double> dp(n + 1, 0.0), next(n + 1, 0.0);
    dp[0] = 1.0;

    for (int step = 0; step < t; ++step) {
        fill(next.begin(), next.end(), 0.0);

        for (int completed = 0; completed < n; ++completed) {
            next[completed] += dp[completed] * (1.0 - p);
            next[completed + 1] += dp[completed] * p;
        }
        next[n] += dp[n];

        dp.swap(next);
    }

    double answer = 0.0;
    for (int completed = 1; completed <= n; ++completed) {
        answer += completed * dp[completed];
    }

    cout << setprecision(10) << answer << '\n';
    return 0;
}

